/// <summary>
/// find last created record by item rec id
/// </summary>
/// <param name = "_inventTableRefRecId">Rec Id of invent table record</param>
/// <param name = "_lastDateTime">upper limit date time</param>
/// <param name = "_forupdate">for update</param>
/// <returns>NDXHK2MGKHistory record</returns>
public static NDXMGKGroupHistory findLast(RefRecId _inventTableRefRecId, utcdatetime _lastDateTime = DateTimeUtil::minValue(), boolean _forupdate = false)
{
    NDXMGKGroupHistory lNDXMGKGroupHistory;

    lNDXMGKGroupHistory.selectForUpdate(_forupdate);

    if(_lastDateTime > DateTimeUtil::minValue())
    {
        select firstonly lNDXMGKGroupHistory order by lNDXMGKGroupHistory.CreatedDateTime desc
            where lNDXMGKGroupHistory.InventTableRefRecId == _inventTableRefRecId
                && lNDXMGKGroupHistory.CreatedDateTime <= _lastDateTime;
    }
    else
    {
        select firstonly lNDXMGKGroupHistory order by lNDXMGKGroupHistory.CreatedDateTime desc
            where lNDXMGKGroupHistory.InventTableRefRecId == _inventTableRefRecId;
    }

    return lNDXMGKGroupHistory;
}

/// <summary>
/// find last created record by item rec id
/// </summary>
/// <param name = "_inventTableRefRecId">Rec Id of invent table record</param>
/// <param name = "_lastDateTime">lower limit date time</param>
/// <param name = "_forupdate">for update</param>
/// <returns>NDXHK2MGKHistory record</returns>
public static NDXMGKGroupHistory findFirst(RefRecId _inventTableRefRecId, utcdatetime _lastDateTime = DateTimeUtil::minValue(), boolean _forupdate = false)
{
    NDXMGKGroupHistory lNDXMGKGroupHistory;

    lNDXMGKGroupHistory.selectForUpdate(_forupdate);

    if(_lastDateTime > DateTimeUtil::minValue())
    {
        select firstonly lNDXMGKGroupHistory order by lNDXMGKGroupHistory.CreatedDateTime asc
        where lNDXMGKGroupHistory.InventTableRefRecId == _inventTableRefRecId
            && lNDXMGKGroupHistory.CreatedDateTime >= _lastDateTime;

        //if there is no record
    }
    else
    {
        select firstonly lNDXMGKGroupHistory order by lNDXMGKGroupHistory.CreatedDateTime asc
            where lNDXMGKGroupHistory.InventTableRefRecId == _inventTableRefRecId;
    }

    return lNDXMGKGroupHistory;
}

/// <summary>
/// Inserts history records for all items with the same MGK group id
/// </summary>
/// <param name = "_AVAMGKFactors">AVAMGKFactors record</param>
public static void createByAVAMGKFactors(AVAMGKFactors _AVAMGKFactors)
{
    NDXMGKGroupHistory lNDXMGKGroupHistory;
    InventTable lInvantTable;
    InventTableModule lInventTableModule;

    AVAMGKGroup groupId = _AVAMGKFactors.MGKGroup;
    AVAMGKFactor factor = _AVAMGKFactors.MGKFactor;

    insert_recordset lNDXMGKGroupHistory(InventTableRefRecId, MGKGroupIdTo, MGKFactorTo)
        select RecId from lInvantTable
            join groupId, factor from lInventTableModule
                where lInventTableModule.ItemId == lInvantTable.ItemId
                    && lInventTableModule.ModuleType == ModuleInventPurchSales::Invent
                    && lInventTableModule.NDXMGKGroupRefRecId == _AVAMGKFactors.RecId;

}

/// <summary>
/// Creates history record by InventTableModule record
/// </summary>
/// <param name = "_inventTableModule">current record</param>
/// <param name = "_orig">original record</param>     
public static void createByInventTableModule(InventTableModule _inventTableModule, InventTableModule _orig)
{
    InventTable inventTable = InventTable::find(_inventTableModule.ItemId);
    NDXMGKGroupHistory lNDXMGKGroupHistory = NDXMGKGroupHistory::findLast(inventTable.RecId, DateTimeUtil::minValue());

    AVAMGKFactors lAVAMGKFactors = AVAMGKFactors::findByRecId(_inventTableModule.NDXMGKGroupRefRecId);
    AVAMGKFactors lAVAMGKFactorsOrig;

    NDXMGKGroupHistory newHistoryRecord;

    // MGK group changed
    if(_orig.NDXMGKGroupRefRecId != _inventTableModule.NDXMGKGroupRefRecId)
    {   
        newHistoryRecord.InventTableRefRecId = inventTable.RecId;
        newHistoryRecord.MGKGroupIdFrom = lNDXMGKGroupHistory.MGKGroupIdTo;
        newHistoryRecord.MGKFactorFrom = lNDXMGKGroupHistory.MGKFactorTo;

        newHistoryRecord.MGKGroupIdTo = lAVAMGKFactors.MGKGroup;
        newHistoryRecord.MGKFactorTo = lAVAMGKFactors.MGKFactor;

        if(_orig)
        {
            lAVAMGKFactorsOrig = AVAMGKFactors::findByRecId(_orig.NDXMGKGroupRefRecId);
            newHistoryRecord.MGKGroupIdFrom = lAVAMGKFactorsOrig.MGKGroup;
            newHistoryRecord.MGKFactorFrom = lAVAMGKFactorsOrig.MGKFactor;
        }

        newHistoryRecord.insert();
    }
}

public void insert()
{
    NDXMGKGroupHistory lNDXMGKGroupHistory = NDXMGKGroupHistory::findLast(this.InventTableRefRecId, DateTimeUtil::minValue());

    if(lNDXMGKGroupHistory && (this.MGKGroupIdTo != lNDXMGKGroupHistory.MGKGroupIdTo || this.MGKFactorTo != lNDXMGKGroupHistory.MGKFactorTo))
    {
        this.MGKGroupIdFrom = lNDXMGKGroupHistory.MGKGroupIdTo;
        this.MGKFactorFrom = lNDXMGKGroupHistory.MGKFactorTo;
    }

    super();

    NDXHK2MGKHistory::createByMGKGroupHistory(this);
}

public static AVAMGKFactor getMGKHistoryFactor(RefRecId _inventTableRefRecId, utcdatetime _lastDateTime = DateTimeUtil::minValue())
{
    NDXMGKGroupHistory lNDXMGKGroupHistory;
    AVAMGKFactor factor = 1;

    lNDXMGKGroupHistory = NDXMGKGroupHistory::findLast(_inventTableRefRecId, _lastDateTime);

    if(lNDXMGKGroupHistory)
    {
        factor = lNDXMGKGroupHistory.MGKFactorTo;
    }

    //if there is no history record for the date, get the first record
    if(!lNDXMGKGroupHistory)
    {
        //the history record exists but the date we are looking for was before the record was created, so the factor is the "from"" factor
        lNDXMGKGroupHistory = NDXMGKGroupHistory::findFirst(_inventTableRefRecId, _lastDateTime);
        factor = lNDXMGKGroupHistory.MGKFactorFrom;
    }

    //if record still does mot exist the we take the current factor
    if(!lNDXMGKGroupHistory)
    {
        InventTable lInventTable = InventTable::findByRecId(_inventTableRefRecId);
        factor = lInventTable.avaGetMGKFactor();
    }

    return factor;
}
